// CHECK-LABEL: define dso_local i32 @uninit_read(
// CHECK-SAME: ) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[BF_EXTRACT:%.*]] = bitextract i5, b32 undef, i32 0
// CHECK-NEXT:    [[BF_CAST:%.*]] = zext i5 [[BF_EXTRACT]] to i32
// CHECK-NEXT:    ret i32 [[BF_CAST]]
//
unsigned uninit_read(void) { struct S1 s; return s.a; }

// CHECK-LABEL: define dso_local i32 @partial_init(
// CHECK-SAME: ) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[BF_SET:%.*]] = bitinsert b32 undef, i5 1, i32 0
// CHECK-NEXT:    [[BF_EXTRACT:%.*]] = bitextract i16, b32 [[BF_SET]], i32 16
// CHECK-NEXT:    [[BF_CAST:%.*]] = zext i16 [[BF_EXTRACT]] to i32
// CHECK-NEXT:    ret i32 [[BF_CAST]]
//
unsigned partial_init(void) { struct S1 s; s.a = 1; return s.c; }

// struct copies and initialisers

// CHECK-LABEL: define dso_local i32 @designated_init(
// CHECK-SAME: ) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[S:%.*]] = alloca [[STRUCT_S1:%.*]], align 4
// CHECK-NEXT:    call void @llvm.memcpy.p0.p0.i32(ptr align 4 [[S]], ptr align 4 @__const.designated_init.s, i32 4, i1 false)
// CHECK-NEXT:    [[BF_LOAD:%.*]] = load b32, ptr [[S]], align 4
// CHECK-NEXT:    [[BF_EXTRACT:%.*]] = bitextract i16, b32 [[BF_LOAD]], i32 16
// CHECK-NEXT:    [[BF_CAST:%.*]] = zext i16 [[BF_EXTRACT]] to i32
// CHECK-NEXT:    ret i32 [[BF_CAST]]
//
unsigned designated_init(void) {
  struct S1 s = { .c = 0xABCD, .a = 3 };
  return s.c;
}

// CHECK-LABEL: define dso_local void @adjacent_stores(
// CHECK-SAME: ptr noundef [[S:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[BF_LOAD:%.*]] = load b32, ptr [[S]], align 4
// CHECK-NEXT:    [[BF_SET:%.*]] = bitinsert b32 [[BF_LOAD]], i5 1, i32 0
// CHECK-NEXT:    store b32 [[BF_SET]], ptr [[S]], align 4
// CHECK-NEXT:    [[BF_LOAD1:%.*]] = load b32, ptr [[S]], align 4
// CHECK-NEXT:    [[BF_SET2:%.*]] = bitinsert b32 [[BF_LOAD1]], i11 2, i32 5
// CHECK-NEXT:    store b32 [[BF_SET2]], ptr [[S]], align 4
// CHECK-NEXT:    [[BF_LOAD3:%.*]] = load b32, ptr [[S]], align 4
// CHECK-NEXT:    [[BF_SET4:%.*]] = bitinsert b32 [[BF_LOAD3]], i16 3, i32 16
// CHECK-NEXT:    store b32 [[BF_SET4]], ptr [[S]], align 4
// CHECK-NEXT:    ret void
//
void adjacent_stores(struct S1 *s) { s->a = 1; s->b = 2; s->c = 3; }
